package com.dongqh.luckyhub.fulfillment.dto;
import com.dongqh.luckyhub.common.exception.BusinessException;import com.dongqh.luckyhub.fulfillment.enums.*;import com.dongqh.luckyhub.fulfillment.model.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;
public record CreateFulfillmentTaskRequest(@NotBlank String fulfillmentNo,@NotBlank String sourceType,@NotBlank String sourceId,@NotNull FulfillmentType fulfillmentType,@NotNull @Positive Long targetUserId,@NotNull @Valid Payload payload,@Min(1) @Max(100) Integer maxAttempts){
 public CreateFulfillmentTaskCommand toCommand(){try{return new CreateFulfillmentTaskCommand(fulfillmentNo,sourceType,sourceId,fulfillmentType,targetUserId,toPayload(),maxAttempts);}catch(IllegalArgumentException|NullPointerException e){throw new BusinessException(FulfillmentErrorCode.INVALID_PAYLOAD);}}
 private FulfillmentPayload toPayload(){return switch(fulfillmentType){case COUPON->new CouponFulfillmentPayload(payload.couponTemplateCode,required(payload.quantity));case POINTS->new PointsFulfillmentPayload(required(payload.points),payload.reason);case MEMBERSHIP->new MembershipFulfillmentPayload(payload.membershipCode,required(payload.durationDays));case LOGISTICS->new LogisticsFulfillmentPayload(payload.skuCode,required(payload.quantity),payload.receiverMasked,payload.phoneMasked,payload.regionMasked);};}
 private static int required(Integer v){if(v==null)throw new IllegalArgumentException();return v;}private static long required(Long v){if(v==null)throw new IllegalArgumentException();return v;}
 public record Payload(String couponTemplateCode,Integer quantity,Long points,String reason,String membershipCode,Integer durationDays,String skuCode,String receiverMasked,String phoneMasked,String regionMasked){}
}
